 s+=f'<div class="education"><h3>{tr("Education","Образование")}</h3><p>{tr("<strong>HSE × YSDA</strong> · Master’s, 2025–present<br><strong>ITMO University</strong> · BSc, Applied Mathematics & Computer Science, 2021–2025<br><strong>Alferov Physics and Technology Lyceum</strong> · 2017–2021","<strong>НИУ ВШЭ × ШАД</strong> · Магистратура, 2025–н. в.<br><strong>Университет ИТМО</strong> · Бакалавриат, прикладная математика и информатика, 2021–2025<br><strong>ФТШ имени Ж. И. Алфёрова</strong> · 2017–2021")}</p></div><p class="outro">{a(tr("Full curriculum vitae · two pages","Полное CV на английском (PDF, 2 страницы)"),cv)}</p></section>'
 s+=section('teaching',3,tr('Sharing what I learn','Преподавание и образовательные проекты'),tr('Courses, technical videos and spaces for learning together.','Курсы, видеолекции и разговорный клуб.'))+'<div class="grid-three">'
