 s+=f'</div><p class="outro">{a(tr("Study notes","Мои конспекты"),"https://github.com/donRumata03/Conspects")} · {a(tr("Economics club recordings","Записи экономического клуба"),"https://www.youtube.com/playlist?list=PLMdakVOACD9XE3PzWCs-CRNVUCjx3BdiG")}</p><article class="book"><p class="eyebrow">{tr("A book in progress · seeking a co-author","Книга в работе · поиск соавтора")}</p><h3>{tr("I’m writing a book about the war of the sexes.","Пишу книгу про войну полов, ищу женщину-соавтора.")}</h3><p>{tr("A discussion-driven project about relationships, gender expectations and the social mechanisms behind them. I’m looking for a woman co-author to bring another perspective and develop the arguments together.","Пишу дискуссионную книгу про отношения, гендерные стереотипы и социальные механизмы. Ищу соавтора-женщину: хочется вместе сопоставлять разные точки зрения и разбирать спорные вопросы.")}</p>{links([[tr("Get in touch about co-authoring","Обсудить соавторство в Telegram"),"https://t.me/donRumata03"]])}</article></section>'
 s+=section('contact',5,tr('Find me elsewhere','Где меня найти'),tr('Research, engineering, teaching, collaboration or a conversation.','По поводу исследований, инженерных проектов, преподавания или книги лучше писать в Telegram.'))
 s+=f'<div class="contact-layout"><div class="contact-direct"><span class="contact-hint">{tr("Preferred contact","Основной контакт")}</span><a class="primary-contact" href="https://t.me/donRumata03">Telegram · @donRumata03</a><a class="email" href="mailto:donrumata03@gmail.com">donrumata03@gmail.com</a><a href="tel:+79995163856">+7 999 516 38 56</a><a href="{cv}" download="Vladimir-Latypov-CV.pdf">{tr("Download the complete CV","Скачать полное CV")} ↓</a></div><div class="profiles">{"".join(a(*p) for p in D["profiles"])}</div></div></section></main><footer class="shell footer"><span>Vladimir Latypov / Владимир Латыпов</span><span>{tr("Updated October 2026","Обновлено в октябре 2026")} · {a(tr("Website source","Исходники сайта"),"https://github.com/donRumata03/donRumata03.github.io")}</span><a href="#about">{tr("Back to top","Наверх")} ↑</a></footer><script src="{pre}assets/site.js" defer></script></body></html>'
